import { useEffect, useMemo, useRef, useState } from 'react';
import {
  Activity, ArrowUpRight, BadgeCheck, Bell, Bot, BriefcaseBusiness, Building2, Check,
  ChevronRight, CircleAlert, ClipboardCheck, Compass, Copy, CopyCheck, Database, Download,
  ExternalLink, FileSearch, FileText, Gauge, LayoutDashboard, Link2, LoaderCircle,
  Mail, MessageSquareText, MoreHorizontal, PauseCircle, Play, Plus, Search, Settings2,
  ShieldCheck, Sparkles, Target, UsersRound, X, Zap,
} from 'lucide-react';
import { seedState } from './data';
import { useAuthUser } from './AuthGate';
import TeamsAndDiagnoses from './Teams';
import OwnerConsole from './OwnerConsole';
import { type BulkSourceRow, type BatchAppliedResult } from './BulkEnrichment';
import Enrichment from './Enrichment';
import { applyBatchEnrichment, applyEnrichmentToAccount, type CompanyExtraction, type ContactCandidate, type PeopleDiscovery } from './enrichment-model';
import EvolutionPanel from './EvolutionPanel';
import type { Account, Activity as ActivityItem, AgentProfile, Campaign, CampaignTask, ChannelConnection, PlaybookStep, ProspectraState, Signal } from './types';

type View = 'dashboard' | 'crm' | 'enrichment' | 'automation' | 'campaigns' | 'operations' | 'teams' | 'owner' | 'settings';
type WorkspaceStatus = 'loading' | 'cloud' | 'local';
type ChannelHealth = { id: 'whatsapp' | 'linkedin'; status: 'connected' | 'not_configured' | 'failed'; capability: 'API autorizada' | 'Assistido' | 'Não configurado'; detail: string; checkedAt: string; provider?: string; latencyMs?: number };
type Notice = { id: string; title: string; detail: string; createdAt: string; view: View; accountId?: string; tone: 'attention' | 'info' | 'blocked' };

const READ_NOTICES_KEY = 'prospectra-notifications-read-v1';
const nav: { id: View; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'dashboard', label: 'Visão geral', icon: LayoutDashboard }, { id: 'crm', label: 'CRM', icon: Building2 },
  { id: 'enrichment', label: 'Enriquecimento', icon: Sparkles }, { id: 'automation', label: 'Automação', icon: Bot },
  { id: 'campaigns', label: 'Campanhas', icon: Target }, { id: 'operations', label: 'Operações', icon: ClipboardCheck },
  { id: 'teams', label: 'Equipes e diagnósticos', icon: FileText }, { id: 'owner', label: 'Painel Owner', icon: ShieldCheck },
  { id: 'settings', label: 'Configurações', icon: Settings2 },
];
const viewPaths: Record<View, string> = { dashboard: '/', crm: '/crm', enrichment: '/enriquecimento', automation: '/automacao', campaigns: '/campanhas', operations: '/operacoes', teams: '/equipes', owner: '/owner', settings: '/configuracoes' };
const pathViews = Object.fromEntries(Object.entries(viewPaths).map(([view, path]) => [path, view])) as Record<string, View>;
function resolveView(pathname: string): View { return pathViews[pathname] ?? 'dashboard'; }
function nowLabel() { return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date()); }
function scoreTone(score: number) { return score >= 80 ? 'score-high' : score >= 65 ? 'score-medium' : 'score-low'; }
function statusTone(value: string) { return ['Ativa', 'Aprovado', 'Revisado', 'Concluído'].includes(value) ? 'good' : ['Pausado', 'Invalidado'].includes(value) ? 'danger' : 'neutral'; }
function csvCell(value: unknown) { return `"${String(value ?? '').replace(/"/g, '""')}"`; }
function downloadCsv(filename: string, rows: unknown[][]) { const blob = new Blob([`\uFEFF${rows.map((row) => row.map(csvCell).join(',')).join('\n')}`], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); }
function profileUrl(value: string) { const candidate = /^https?:\/\//i.test(value) ? value : `https://${value}`; try { const url = new URL(candidate); if (url.hostname.toLowerCase() === 'linkedin.com') url.hostname = 'www.linkedin.com'; return url.toString(); } catch { return candidate; } }
function normalizedImportHeader(value: string) { return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
function importValue(values: Record<string, string>, hints: string[]) { const entry = Object.entries(values).find(([key, value]) => hints.some((hint) => normalizedImportHeader(key).includes(hint)) && value.trim()); return entry?.[1]?.trim() ?? ''; }
function stripUrl(value: string) { try { const parsed = new URL(/^https?:\/\//i.test(value) ? value : `https://${value}`); return ['http:', 'https:'].includes(parsed.protocol) ? parsed.hostname.toLowerCase().replace(/^www\./, '').replace(/\.$/, '') : ''; } catch { return ''; } }
function importLinkedInProfile(value: string) { try { const parsed = new URL(/^https?:\/\//i.test(value) ? value : `https://${value}`); return parsed.protocol === 'https:' && ['linkedin.com', 'www.linkedin.com'].includes(parsed.hostname.toLowerCase()) && /^\/(in|pub)\/[^/]+/i.test(parsed.pathname) ? parsed.toString() : ''; } catch { return ''; } }

export default function App() {
  const [view, setView] = useState<View>(() => resolveView(window.location.pathname));
  const [state, setState] = useState<ProspectraState>(() => JSON.parse(JSON.stringify(seedState)) as ProspectraState);
  const [workspaceStatus, setWorkspaceStatus] = useState<WorkspaceStatus>('loading');
  const [toast, setToast] = useState('');
  const [search, setSearch] = useState('');
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [readNoticeIds, setReadNoticeIds] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem(READ_NOTICES_KEY) ?? '[]') as string[]; } catch { return []; } });
  const [composerOpen, setComposerOpen] = useState(false);
  const [limitsOpen, setLimitsOpen] = useState(false);
  const [cloudLoaded, setCloudLoaded] = useState(false);
  const authUser = useAuthUser();
  const saveTimer = useRef<number | undefined>(undefined);

  useEffect(() => { let alive = true; if (!authUser) return () => { alive = false; }; fetch('/api/workspace/state', { credentials: 'include' }).then(async (response) => { const payload = await response.json().catch(() => ({})); if (!alive) return; if (response.ok && payload.state) { setState(payload.state as ProspectraState); setWorkspaceStatus('cloud'); } else { setWorkspaceStatus('local'); setToast('Não foi possível carregar o workspace privado. Nenhum snapshot de outro usuário foi utilizado.'); } setCloudLoaded(true); }).catch(() => { if (alive) { setWorkspaceStatus('local'); setCloudLoaded(true); setToast('Não foi possível carregar o workspace privado. Nenhum snapshot local foi reutilizado.'); } }); return () => { alive = false; }; }, [authUser?.id]);
  useEffect(() => { if (!cloudLoaded || workspaceStatus !== 'cloud' || authUser?.role !== 'admin') return; window.clearTimeout(saveTimer.current); saveTimer.current = window.setTimeout(() => { void fetch('/api/workspace/state', { method: 'PUT', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ state }) }).then((response) => { if (!response.ok) throw new Error('workspace_save_failed'); }).catch(() => { setWorkspaceStatus('local'); setToast('Não foi possível sincronizar o workspace. As próximas alterações não serão tratadas como salvas.'); }); }, 500); return () => window.clearTimeout(saveTimer.current); }, [state, cloudLoaded, workspaceStatus, authUser?.role]);
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(''), 3800); return () => window.clearTimeout(id); }, [toast]);
  useEffect(() => { const onPopState = () => setView(resolveView(window.location.pathname)); window.addEventListener('popstate', onPopState); return () => window.removeEventListener('popstate', onPopState); }, []);
  useEffect(() => { localStorage.setItem(READ_NOTICES_KEY, JSON.stringify(readNoticeIds)); }, [readNoticeIds]);

  const selectedAccount = state.accounts.find((account) => account.id === state.selectedAccountId) ?? state.accounts[0];
  const selectedCampaign = state.campaigns.find((campaign) => campaign.id === state.selectedCampaignId) ?? state.campaigns[0];
  const activeAccounts = state.accounts.filter((account) => !account.paused && !account.suppressed).length;
  const reviewedContacts = state.accounts.flatMap((account) => account.contacts).filter((contact) => contact.status === 'Revisado').length;
  const verifiedEvidence = state.accounts.flatMap((account) => account.evidence).filter((evidence) => evidence.verified).length;
  const pendingTasks = selectedCampaign?.tasks.filter((task) => task.state !== 'Concluído').length ?? 0;
  const notifications = useMemo<Notice[]>(() => {
    const signalNotices = state.signals.filter((signal) => signal.state !== 'Resolvido').map((signal) => ({ id: `signal-${signal.id}`, title: signal.title, detail: signal.detail, createdAt: signal.createdAt, view: 'automation' as View, accountId: signal.accountId, tone: signal.priority === 'Alta' ? 'attention' as const : 'info' as const }));
    const taskNotices = state.campaigns.flatMap((campaign) => campaign.tasks.filter((task) => task.state === 'Aguardando revisão' || task.state === 'Aprovado').map((task) => ({ id: `task-${task.id}`, title: task.title, detail: `${campaign.name} · ${task.channel} · ${task.state}`, createdAt: task.due, view: 'campaigns' as View, accountId: task.accountId, tone: task.state === 'Aprovado' ? 'info' as const : 'attention' as const })));
    return [...signalNotices, ...taskNotices].slice(0, 30);
  }, [state]);
  const unreadCount = notifications.filter((notice) => !readNoticeIds.includes(notice.id)).length;

  const navigate = (nextView: View) => { setView(nextView); const path = viewPaths[nextView]; if (window.location.pathname !== path) window.history.pushState({}, '', path); setNotificationsOpen(false); };
  const updateAccount = (accountId: string, patch: Partial<Account>, activity?: Omit<ActivityItem, 'id' | 'createdAt'>) => setState((current) => ({ ...current, accounts: current.accounts.map((account) => account.id !== accountId ? account : { ...account, ...patch, activities: activity ? [{ id: crypto.randomUUID(), createdAt: nowLabel(), ...activity }, ...account.activities] : account.activities }) }));
  const openAccount = (id: string) => { setState((current) => ({ ...current, selectedAccountId: id })); navigate('crm'); };
  const resetDemo = () => { setState(JSON.parse(JSON.stringify(seedState)) as ProspectraState); setToast('Dados demonstrativos restaurados no workspace atual e aguardando sincronização.'); };
  const addAccount = (draft: { name: string; domain: string; sector: string; employees: string; journey: Account['journey']; owner: string }) => { const account: Account = { id: `a-${crypto.randomUUID()}`, name: draft.name, domain: draft.domain.replace(/^https?:\/\//, '').replace(/\/$/, ''), sector: draft.sector, employees: draft.employees, tier: 'Tier 2', journey: draft.journey, relationship: 'Prospect', owner: draft.owner, score: 50, scoreReason: 'Conta recém-cadastrada; exige evidência e revisão', stage: 'A revisar', paused: false, suppressed: false, contacts: [], evidence: [], activities: [{ id: crypto.randomUUID(), kind: 'Nota', text: 'Conta cadastrada no CRM pelo operador.', createdAt: nowLabel(), actor: authUser?.name ?? 'Operador' }] }; setState((current) => ({ ...current, accounts: [account, ...current.accounts], selectedAccountId: account.id })); setComposerOpen(false); navigate('crm'); setToast('Conta criada e pronta para pesquisa.'); };
  const importAccounts = (rows: BulkSourceRow[]) => {
    let created = 0;
    let updated = 0;
    setState((current) => {
      const accounts = current.accounts.map((account) => ({ ...account }));
      for (const row of rows) {
        const name = importValue(row.values, ['empresa', 'company', 'companyname', 'nome', 'razao', 'razaosocial', 'account']) || `Empresa importada · linha ${row.index}`;
        const domain = stripUrl(importValue(row.values, ['url', 'website', 'site', 'dominio', 'domain', 'homepage', 'pagina']));
        const sector = importValue(row.values, ['setor', 'sector', 'industria', 'industry']) || 'Não informado';
        const employees = importValue(row.values, ['funcionarios', 'employees', 'porte', 'size']) || 'Não informado';
        const journeyValue = importValue(row.values, ['jornada', 'journey']);
        const journey: Account['journey'] = journeyValue.includes('Expans') ? 'Expansão / ABM' : journeyValue.includes('Reativ') ? 'Reativação' : 'Aquisição';
        const scoreText = importValue(row.values, ['score', 'pontuacao', 'prioridade']).replace(',', '.');
        const numericScore = scoreText ? Number(scoreText) : NaN;
        const scoreValue = numericScore >= 0 && numericScore <= 100 ? numericScore : NaN;
        const contactName = importValue(row.values, ['contactname', 'nomecontato', 'decisor', 'contato']);
        const contactEmail = importValue(row.values, ['contactemail', 'emailcontato', 'email', 'e-mail']);
        const contactLinkedIn = importLinkedInProfile(importValue(row.values, ['linkedin', 'linkedinurl', 'perfil']));
        const contactPhone = importValue(row.values, ['phone', 'telefone', 'celular', 'whatsapp', 'numero', 'mobile']);
        const contactRole = importValue(row.values, ['contactrole', 'cargocontato', 'cargo', 'role']) || 'Contato importado';
        const evidenceUrl = importValue(row.values, ['evidenceurl', 'sourceurl', 'urlfonte', 'fonteurl', 'evidencia']);
        const evidenceExcerpt = importValue(row.values, ['evidenceexcerpt', 'excerpt', 'trecho', 'contexto', 'descricao']);
        const contact = contactName || contactEmail || contactLinkedIn || contactPhone ? { id: `contact-${crypto.randomUUID()}`, name: contactName || contactEmail || contactPhone || 'Contato importado', role: contactRole, email: contactEmail, phone: contactPhone || undefined, linkedin: contactLinkedIn, reviewedAt: '', status: 'A revisar' as const, sourceUrl: evidenceUrl || undefined } : null;
        const evidence = evidenceUrl ? { id: `evidence-${crypto.randomUUID()}`, title: importValue(row.values, ['evidenciatitulo', 'evidencetitle', 'titulo']) || 'Evidência importada', url: profileUrl(evidenceUrl), excerpt: evidenceExcerpt || 'Evidência trazida pela base do operador.', source: 'Importação' as const, collectedAt: importValue(row.values, ['collectedat', 'datacoleta', 'data']) || nowLabel(), verified: false } : null;
        const match = accounts.find((account) => (domain && account.domain.toLowerCase() === domain.toLowerCase()) || account.name.toLowerCase() === name.toLowerCase());
        if (match) {
          match.sector = sector !== 'Não informado' ? sector : match.sector;
          match.employees = employees !== 'Não informado' ? employees : match.employees;
          match.score = Number.isFinite(scoreValue) ? scoreValue : match.score;
          match.evidence = evidence ? [evidence, ...match.evidence] : match.evidence;
          match.contacts = contact && !match.contacts.some((item) => (contact.email && item.email === contact.email) || (contact.phone && item.phone === contact.phone) || (contact.linkedin && item.linkedin === contact.linkedin)) ? [contact, ...match.contacts] : match.contacts;
          match.activities = [{ id: crypto.randomUUID(), kind: 'Nota', actor: authUser?.name ?? 'Operador', createdAt: nowLabel(), text: `Dados enriquecidos importados da base ${row.index}; nenhuma chamada ao ScrapeGraphAI foi realizada.` }, ...match.activities];
          updated += 1;
        } else {
          const account: Account = { id: `a-${crypto.randomUUID()}`, name, domain, sector, employees, tier: 'Tier 2', journey, relationship: 'Prospect', owner: importValue(row.values, ['owner', 'responsavel', 'proprietario']) || authUser?.name || 'Não atribuído', score: Number.isFinite(scoreValue) ? scoreValue : 50, scoreReason: 'Dados importados; validar evidências antes da abordagem', stage: importValue(row.values, ['stage', 'etapa', 'status']) || 'A revisar', paused: false, suppressed: false, contacts: contact ? [contact] : [], evidence: evidence ? [evidence] : [], activities: [{ id: crypto.randomUUID(), kind: 'Nota', text: `Conta importada da base na linha ${row.index}; fonte externa não consultada pelo Prospectra.`, createdAt: nowLabel(), actor: authUser?.name ?? 'Operador' }] };
          accounts.unshift(account); created += 1;
        }
      }
      return { ...current, accounts, selectedAccountId: accounts[0]?.id ?? current.selectedAccountId };
    });
    setToast('Importação incorporada ao CRM; nenhuma chamada ao ScrapeGraphAI foi realizada.');
  };
  const pauseTasksForAccount = (accountId: string) => setState((current) => ({ ...current, campaigns: current.campaigns.map((campaign) => ({ ...campaign, tasks: campaign.tasks.map((task) => task.accountId === accountId && task.state !== 'Concluído' ? { ...task, state: 'Pausado' as const } : task) })) }));
  const recordAssistedTask = (task: CampaignTask) => { const campaign = state.campaigns.find((item) => item.tasks.some((candidate) => candidate.id === task.id)); const account = state.accounts.find((item) => item.id === task.accountId); if (!campaign || !account) return setToast('A tarefa não pertence a uma campanha ou conta válida.'); if (campaign.copy.state !== 'Aprovado' || task.approval?.copyRevision !== campaign.copy.revision || task.approval.contactId !== task.contactId || task.approval.channel !== task.channel || !task.approval.evidenceIds.length) return setToast('A tarefa não tem aprovação válida para a revisão, destinatário, canal e evidências atuais.'); if (account.paused || account.suppressed) return setToast('A conta está pausada ou suprimida; nenhuma tarefa pode ser concluída.'); if (task.state === 'Concluído') return setToast('Esta tarefa já foi registrada.'); setState((current) => ({ ...current, campaigns: current.campaigns.map((item) => ({ ...item, tasks: item.tasks.map((candidate) => candidate.id === task.id ? { ...candidate, state: 'Concluído' as const } : candidate) })), accounts: current.accounts.map((item) => item.id !== task.accountId ? item : { ...item, activities: [{ id: crypto.randomUUID(), kind: 'Tarefa', actor: authUser?.name ?? 'Operador', createdAt: nowLabel(), text: `Ação assistida registrada no ${task.channel} para ${account.contacts.find((contact) => contact.id === task.contactId)?.name ?? 'contato'}. Isso não confirma entrega do provedor.` }, ...item.activities] }) })); setToast('Ação assistida registrada e auditada. Entrega externa não foi presumida.'); };
  const assistTask = async (task: CampaignTask, action: 'profile' | 'copy' | 'complete') => { const campaign = state.campaigns.find((item) => item.tasks.some((candidate) => candidate.id === task.id)); const account = state.accounts.find((item) => item.id === task.accountId); const contact = account?.contacts.find((item) => item.id === task.contactId); if (!campaign || !account || !contact) return setToast('A tarefa precisa de campanha, conta e contato válidos.'); if (account.paused || account.suppressed) return setToast('A conta está pausada ou suprimida; nenhuma ação de prospecção é permitida.'); if (action === 'profile') { window.open(profileUrl(contact.linkedin), '_blank', 'noopener,noreferrer'); return; } if (campaign.copy.state !== 'Aprovado' || task.approval?.copyRevision !== campaign.copy.revision || task.approval.contactId !== task.contactId || task.approval.channel !== task.channel || !task.approval.evidenceIds.length) return setToast('A tarefa precisa de aprovação específica para a revisão, destinatário, canal e evidências atuais.'); if (action === 'copy') { try { await navigator.clipboard.writeText(campaign.copy.text); setToast('Copy aprovada copiada. Execute a ação diretamente na plataforma autorizada.'); } catch { setToast('O navegador bloqueou a cópia; selecione o texto na campanha.'); } return; } recordAssistedTask(task); };
  const exportAudit = () => { const rows: unknown[][] = [['conta', 'tipo', 'texto', 'ator', 'data'], ...state.accounts.flatMap((account) => account.activities.map((activity) => [account.name, activity.kind, activity.text, activity.actor, activity.createdAt]))]; downloadCsv(`prospectra-auditoria-${new Date().toISOString().slice(0, 10)}.csv`, rows); setToast('Auditoria exportada em CSV.'); };  const queueBridgeTask = async (task: CampaignTask) => { const campaign = state.campaigns.find((item) => item.tasks.some((candidate) => candidate.id === task.id)); const account = state.accounts.find((item) => item.id === task.accountId); const contact = account?.contacts.find((item) => item.id === task.contactId); if (!campaign || !account || !contact) return setToast('A tarefa precisa de campanha, conta e contato válidos.'); if (campaign.copy.state !== 'Aprovado' || task.approval?.copyRevision !== campaign.copy.revision || task.approval.contactId !== task.contactId || task.approval.channel !== task.channel || !task.approval.evidenceIds.length) return setToast('A tarefa precisa de aprovação específica para a revisão, destinatário, canal e evidências atuais.'); if (account.paused || account.suppressed) return setToast('A conta está pausada ou suprimida; nenhum job foi criado.'); try { if (task.channel === 'LinkedIn') { if (!contact.linkedin) return setToast('O contato não possui URL LinkedIn válida.'); const response = await fetch('/api/integrations/prospecting/bridge/tasks', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'send_message', profileUrl: profileUrl(contact.linkedin), message: campaign.copy.text, campaignTaskId: task.id, accountId: account.id, contactId: contact.id }) }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(String(payload.error ?? 'bridge_task_failed')); setToast('Job enviado ao Abridge. A confirmação final será feita no desktop.'); return; } if (task.channel === 'WhatsApp') { if (!contact.phone) return setToast('O contato não possui telefone. Importe um número internacional no CSV/XLSX antes do envio.'); const response = await fetch('/api/integrations/whatsapp/send', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ campaignTaskId: task.id, accountId: account.id, contactId: contact.id, number: contact.phone, text: campaign.copy.text }) }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(String(payload.error ?? 'evolution_send_failed')); setState((current) => ({ ...current, campaigns: current.campaigns.map((item) => ({ ...item, tasks: item.tasks.map((candidate) => candidate.id === task.id ? { ...candidate, state: 'Concluído' as const } : candidate) })), accounts: current.accounts.map((item) => item.id !== account.id ? item : { ...item, activities: [{ id: crypto.randomUUID(), kind: 'Tarefa', actor: authUser?.name ?? 'Operador', createdAt: nowLabel(), text: `Mensagem WhatsApp enviada pela Evolution API para ${contact.name}. Provider ID: ${String(payload.receipt?.providerMessageId ?? 'n/d')}.` }, ...item.activities] }) })); setToast('Mensagem enviada pela Evolution API e registrada na auditoria.'); } } catch (error) { const code = error instanceof Error ? error.message : ''; setToast(code === 'evolution_not_configured' ? 'Evolution API não configurada. Abra Configurações para validar URL, chave, instância e webhook.' : 'Não foi possível executar o envio. Verifique o health check e os dados aprovados.'); } };

  const markRead = (id: string) => setReadNoticeIds((current) => current.includes(id) ? current : [...current, id]);
  const markAllRead = () => setReadNoticeIds((current) => [...new Set([...current, ...notifications.map((notice) => notice.id)])]);
  const handleNotice = (notice: Notice) => { markRead(notice.id); if (notice.accountId) setState((current) => ({ ...current, selectedAccountId: notice.accountId ?? current.selectedAccountId })); navigate(notice.view); };

  if (workspaceStatus === 'loading' || !cloudLoaded) return <div className="auth-shell"><div className="auth-panel"><LoaderCircle className="spin"/><p>Autorizando e carregando workspace seguro…</p></div></div>;
  if (!selectedAccount || !selectedCampaign) return <div className="auth-shell"><div className="auth-panel"><LoaderCircle className="spin"/><p>Carregando workspace…</p></div></div>;
  return <div className="app-shell">
    <aside className="sidebar"><div className="brand-block"><div className="brand-mark"><img src="/prospectra-logo.svg" alt="Símbolo Trilha do Prospectra+" /></div><div><strong>prospectra<span>+</span></strong><small>revenue intelligence</small></div></div><div className="workspace-card"><div className="workspace-dot">AP</div><div><span>Workspace</span><strong>Argus Prime</strong></div><ChevronRight size={16}/></div><nav>{nav.filter((item) => item.id !== 'owner' || authUser?.role === 'admin').map(({ id, label, icon: Icon }) => <button key={id} onClick={() => navigate(id)} className={`nav-item ${view === id ? 'active' : ''}`}><Icon size={18}/><span>{label}</span>{id === 'operations' && pendingTasks > 0 && <b>{pendingTasks}</b>}</button>)}</nav><div className="sidebar-foot"><div className="operator"><div className="avatar">{(authUser?.name ?? 'AT').slice(0, 2).toUpperCase()}</div><div><strong>{authUser?.name ?? 'André Tintilio'}</strong><span>{authUser?.role === 'admin' ? 'Owner' : authUser?.role === 'leader' ? 'Líder' : 'Liderado'}</span></div><MoreHorizontal size={18}/></div></div></aside>
    <main><header className="topbar"><div className="crumb"><span>Prospectra+</span><ChevronRight size={14}/><strong>{nav.find((item) => item.id === view)?.label}</strong></div><div className="top-actions"><label className="global-search"><Search size={16}/><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar conta, contato ou sinal" /></label><div className="notification-wrap"><button className={`icon-button ${notificationsOpen ? 'active' : ''}`} onClick={() => setNotificationsOpen((open) => !open)} aria-label="Abrir notificações"><Bell size={18}/>{unreadCount > 0 && <b>{unreadCount > 9 ? '9+' : unreadCount}</b>}<i></i></button>{notificationsOpen && <NotificationCenter notifications={notifications} unreadCount={unreadCount} readIds={readNoticeIds} onRead={markRead} onReadAll={markAllRead} onOpen={handleNotice}/>}</div><button className="new-button" onClick={() => setComposerOpen(true)}><Plus size={17}/> Nova conta</button></div></header><section className="content"><DemoNotice workspaceStatus={workspaceStatus} onLimits={() => setLimitsOpen(true)} /><div className="workspace-state-bar"><span className={`workspace-dot-status ${workspaceStatus}`}></span><span>{workspaceStatus === 'cloud' ? 'Workspace sincronizado no armazenamento privado' : 'Modo local temporário — a persistência server-side não respondeu'}</span></div>{view === 'dashboard' && <Dashboard accounts={state.accounts} activeAccounts={activeAccounts} reviewedContacts={reviewedContacts} verifiedEvidence={verifiedEvidence} pendingTasks={pendingTasks} onOpen={openAccount} onNavigate={navigate} />}{view === 'crm' && <CRM accounts={state.accounts} selected={selectedAccount} search={search} onSelect={(id) => setState((current) => ({ ...current, selectedAccountId: id }))} onAdd={() => setComposerOpen(true)} onReply={() => { pauseTasksForAccount(selectedAccount.id); updateAccount(selectedAccount.id, { paused: true }, { kind: 'Resposta', actor: 'Inbox assistido', text: 'Resposta registrada. Todas as ações comerciais pendentes da conta foram pausadas para revisão.' }); setToast('Conta e tarefas pendentes pausadas para revisão humana.'); }} onSuppress={() => { pauseTasksForAccount(selectedAccount.id); updateAccount(selectedAccount.id, { suppressed: true, paused: true }, { kind: 'Nota', actor: 'Gestor', text: 'Oposição registrada. A conta e toda a fila permanecem suprimidas sem reativação automática.' }); setToast('Oposição registrada; conta e tarefas foram suprimidas.'); }} canReview={workspaceStatus === 'cloud' && authUser?.role === 'admin'} onVerifyEvidence={(evidenceId) => {
  const entry = selectedAccount.evidence.find((item) => item.id === evidenceId);
  if (!entry?.url || !entry.excerpt) return setToast('Abra uma fonte e um trecho válidos antes de verificar.');
  setState((current) => ({ ...current, accounts: current.accounts.map((account) => account.id !== selectedAccount.id ? account : {
    ...account, evidence: account.evidence.map((item) => item.id === evidenceId ? { ...item, verified: true, verifiedBy: authUser?.name ?? 'Owner', verifiedAt: new Date().toISOString() } : item),
    activities: [{ id: crypto.randomUUID(), kind: 'Aprovação' as const, actor: authUser?.name ?? 'Owner', createdAt: nowLabel(), text: `Evidência ${entry.title} verificada após revisão da fonte ${entry.url}.` }, ...account.activities],
  }) })); setToast('Evidência marcada como verificada pelo Owner; sincronização em andamento.');
}} onReviewContact={(contactId) => {
  setState((current) => ({ ...current, accounts: current.accounts.map((account) => account.id !== selectedAccount.id ? account : {
    ...account, contacts: account.contacts.map((contact) => contact.id === contactId ? { ...contact, status: 'Revisado' as const, reviewedAt: nowLabel() } : contact),
    activities: [{ id: crypto.randomUUID(), kind: 'Aprovação' as const, actor: authUser?.name ?? 'Owner', createdAt: nowLabel(), text: `Contato revisado no CRM: ${account.contacts.find((c) => c.id === contactId)?.name ?? contactId}. A revisão não concede opt-in para mensagens.` }, ...account.activities],
  }) })); setToast('Contato revisado; consentimento para WhatsApp permanece separado.');
}} />}{view === 'enrichment' && <Enrichment selected={selectedAccount} writable={workspaceStatus === 'cloud' && authUser?.role === 'admin'} onImportRows={importAccounts} onApply={(accountId: string, extraction: CompanyExtraction | PeopleDiscovery, contacts: ContactCandidate[]) => { setState((current) => ({ ...current, accounts: current.accounts.map((account) => account.id === accountId ? applyEnrichmentToAccount(account, extraction, contacts, authUser?.name ?? 'Operador') : account) })); setToast('Sugestões adicionadas ao CRM para revisão; sincronização em andamento.'); }} onApplyBatch={(results: BatchAppliedResult[]) => { setState((current) => ({ ...current, accounts: applyBatchEnrichment(current.accounts, results, authUser?.name ?? 'Operador').accounts })); setToast('Resultados do lote adicionados ao CRM para revisão; sincronização em andamento.'); }} />}{view === 'automation' && <Automation channels={state.channels} agent={state.agent} playbook={state.playbook} signals={state.signals} accounts={state.accounts} onChange={(next) => setState((current) => ({ ...current, ...next }))} onToast={setToast} onNavigate={navigate} />}{view === 'campaigns' && <Campaigns campaign={selectedCampaign} accounts={state.accounts} onChange={(next) => setState((current) => ({ ...current, campaigns: current.campaigns.map((campaign) => campaign.id === next.id ? next : campaign) }))} onPauseAccount={(accountId) => { pauseTasksForAccount(accountId); updateAccount(accountId, { paused: true }, { kind: 'Tarefa', actor: 'Campanha', text: 'Ações da campanha e tarefas pendentes foram pausadas manualmente pelo operador.' }); setToast('Ações e tarefas da conta pausadas.'); }} onAssist={assistTask} onQueue={queueBridgeTask} onToast={setToast} />}{view === 'operations' && <Operations accounts={state.accounts} campaign={selectedCampaign} onComplete={recordAssistedTask} onExport={exportAudit} />}{view === 'teams' && <TeamsAndDiagnoses user={authUser} teams={state.teams} members={state.members} opportunities={state.opportunities} diagnoses={state.diagnoses} accounts={state.accounts} />}{view === 'owner' && authUser?.role === 'admin' && <OwnerConsole currentUser={authUser} onOrganizationChange={(organization) => setState((current) => ({ ...current, members: organization.users.map((user) => ({ id: user.id, name: user.name, email: user.email, role: user.role === 'admin' ? 'Administrador' : user.role === 'leader' ? 'Líder' : 'Liderado', teamId: user.teamId ?? undefined })), teams: organization.teams.map((team) => ({ id: team.id, name: team.name, leaderId: team.leaderId, memberIds: team.memberIds, color: team.color })) }))} />}{view === 'owner' && authUser?.role !== 'admin' && <AccessRestricted />}{view === 'settings' && <Settings onReset={resetDemo} onNavigate={navigate} onToast={setToast} />}</section></main>{toast && <div className="toast"><BadgeCheck size={18}/>{toast}<button onClick={() => setToast('')}><X size={15}/></button></div>}{composerOpen && <AccountComposer owner={authUser?.name ?? 'Operador'} onClose={() => setComposerOpen(false)} onCreate={addAccount} />}{limitsOpen && <LimitsDialog onClose={() => setLimitsOpen(false)} />}</div>;
}

function NotificationCenter({ notifications, unreadCount, readIds, onRead, onReadAll, onOpen }: { notifications: Notice[]; unreadCount: number; readIds: string[]; onRead: (id: string) => void; onReadAll: () => void; onOpen: (notice: Notice) => void }) { return <div className="notification-panel"><div className="notification-head"><div><span className="eyebrow">CENTRAL DE ATENÇÃO</span><h2>Notificações</h2></div><span className="status-tag neutral">{unreadCount} não lidas</span></div><div className="notification-actions"><button className="text-button" onClick={onReadAll} disabled={!unreadCount}><Check size={14}/> Marcar todas como lidas</button></div><div className="notification-list">{notifications.length === 0 ? <div className="notification-empty">Tudo em dia. Não há sinais ou tarefas pendentes.</div> : notifications.map((notice) => <button className={`notification-item ${readIds.includes(notice.id) ? 'read' : ''}`} key={notice.id} onClick={() => onOpen(notice)}><span className={`notification-dot ${notice.tone}`}></span><span><strong>{notice.title}</strong><small>{notice.detail}</small><em>{notice.createdAt}</em></span>{!readIds.includes(notice.id) && <i></i>}</button>)}</div></div>; }
function DemoNotice({ workspaceStatus, onLimits }: { workspaceStatus: WorkspaceStatus; onLimits: () => void }) { return <div className="demo-notice"><CircleAlert size={16}/><span><strong>{workspaceStatus === 'cloud' ? 'Workspace operacional.' : 'Estado de operação.'}</strong> {workspaceStatus === 'cloud' ? 'CRM, campanhas e auditoria sincronizam no armazenamento privado após autenticação.' : 'O produto está em modo local enquanto a persistência server-side responde.'}</span><button onClick={onLimits}>Ver capacidades e limites</button></div>; }
function AccessRestricted() { return <div className="owner-error"><strong>Acesso restrito ao Owner.</strong><span>Usuários líderes e liderados não administram pessoas, equipes ou permissões do workspace.</span></div>; }
function Dashboard({ accounts, activeAccounts, reviewedContacts, verifiedEvidence, pendingTasks, onOpen, onNavigate }: { accounts: Account[]; activeAccounts: number; reviewedContacts: number; verifiedEvidence: number; pendingTasks: number; onOpen: (id: string) => void; onNavigate: (view: View) => void }) { return <><div className="page-intro"><div><p className="eyebrow">OPERAÇÃO DE RECEITA</p><h1>Decisões comerciais com <em>proveniência.</em></h1><p>Priorize contas com contexto verificável, mantenha a aprovação humana e acompanhe o que realmente avança.</p></div><button className="outline-button" onClick={() => onNavigate('operations')}><FileSearch size={17}/> Ver auditoria</button></div><div className="metrics-grid"><Metric icon={Target} label="Contas elegíveis" value={activeAccounts.toString()} detail="sem oposição persistente" tone="purple"/><Metric icon={Gauge} label="Score médio" value={accounts.length ? String(Math.round(accounts.reduce((sum, account) => sum + (Number.isFinite(account.score) ? account.score : 0), 0) / accounts.length)) : "0"} detail="média das contas visíveis" tone="emerald"/><Metric icon={BadgeCheck} label="Evidências verificadas" value={verifiedEvidence.toString()} detail="fonte e data preservadas" tone="lilac"/><Metric icon={ClipboardCheck} label="Ações em revisão" value={pendingTasks.toString()} detail={`${reviewedContacts} contatos revisados`} tone="neutral"/></div><div className="dashboard-grid"><section className="panel opportunity-panel"><div className="panel-head"><div><span className="eyebrow">FILA DE PRIORIDADE</span><h2>Contas que merecem atenção</h2></div><button className="text-button" onClick={() => onNavigate('crm')}>Ver CRM <ArrowUpRight size={15}/></button></div><div className="account-list">{accounts.slice(0, 12).map((account) => <button className="account-row" onClick={() => onOpen(account.id)} key={account.id}><div className="company-glyph">{account.name.slice(0, 1)}</div><div className="account-main"><strong>{account.name}</strong><span>{account.sector} · {account.journey}</span></div><div className="account-signal"><span className={`dot ${account.paused ? 'paused' : ''}`}></span>{account.paused ? 'Pausada' : account.scoreReason}</div><div className={`score-pill ${scoreTone(account.score)}`}>{account.score}</div><ChevronRight size={17}/></button>)}</div></section><section className="panel insight-panel"><div className="panel-head"><div><span className="eyebrow">MOTOR DE CONTEXTO</span><h2>O que mudou hoje</h2></div><Sparkles size={19} className="spark"/></div><div className="insight-orbit"><div className="orbit-ring ring-a"></div><div className="orbit-ring ring-b"></div><div className="center-signal"><Compass size={24}/></div><span className="signal-node node-one"></span><span className="signal-node node-two"></span><span className="signal-node node-three"></span></div><div className="insight-copy"><strong>{accounts.reduce((sum, account) => sum + account.evidence.filter((evidence) => !evidence.verified).length, 0)} evidências aguardam revisão</strong><p>Abra uma fonte, valide o contexto e selecione os contatos certos antes de criar uma abordagem.</p><button className="text-button" onClick={() => onNavigate('enrichment')}>Abrir evidências <ArrowUpRight size={15}/></button></div></section></div></>; }
function Metric({ icon: Icon, label, value, detail, tone }: { icon: typeof Target; label: string; value: string; detail: string; tone: string }) { return <article className={`metric-card ${tone}`}><div className="metric-icon"><Icon size={19}/></div><span>{label}</span><strong>{value}</strong><small>{detail}</small></article>; }

function CRM({ accounts, selected, search, onSelect, onAdd, onReply, onSuppress, onVerifyEvidence, onReviewContact, canReview }: { accounts: Account[]; selected: Account; search: string; onSelect: (id: string) => void; onAdd: () => void; onReply: () => void; onSuppress: () => void; onVerifyEvidence: (id: string) => void; onReviewContact: (id: string) => void; canReview: boolean }) {
  const [stage, setStage] = useState('Todos');
  const filtered = useMemo(() => accounts.filter((account) => (stage === 'Todos' || account.stage === stage) && `${account.name} ${account.sector} ${account.contacts.map((contact) => contact.name).join(' ')}`.toLowerCase().includes(search.toLowerCase())), [accounts, search, stage]);
  const stages = Array.from(new Set(accounts.map((account) => account.stage)));
  return <><div className="section-title"><div><p className="eyebrow">CRM NATIVO</p><h1>Contas, contexto e próximo passo.</h1><p>Contas, contatos, evidências, atividades e pausas permanecem no workspace autenticado.</p></div><button className="new-button" onClick={onAdd}><Plus size={17}/> Adicionar conta</button></div><div className="crm-layout"><section className="panel crm-list"><div className="list-tools"><strong>{filtered.length} contas</strong><select className="filter-chip" value={stage} onChange={(event) => setStage(event.target.value)}><option>Todos</option>{stages.map((value) => <option key={value}>{value}</option>)}</select></div>{filtered.map((account) => <button onClick={() => onSelect(account.id)} key={account.id} className={`crm-row ${account.id === selected.id ? 'selected' : ''}`}><div className="company-glyph">{account.name[0]}</div><div><strong>{account.name}</strong><span>{account.stage} · {account.owner}</span></div><div className={`score-pill ${scoreTone(account.score)}`}>{account.score}</div></button>)}</section><section className="panel account-detail"><div className="detail-top"><div><div className="account-heading"><div className="company-glyph large">{selected.name[0]}</div><div><p className="eyebrow">{selected.relationship} · {selected.tier}</p><h2>{selected.name}</h2><a href={selected.domain.includes('.example') ? undefined : `https://${selected.domain}`} target="_blank" rel="noreferrer">{selected.domain}{!selected.domain.includes('.example') && <ExternalLink size={13}/>}</a></div></div><div className="detail-tags"><span className={`status-tag ${selected.paused ? 'danger' : 'good'}`}>{selected.paused ? 'Ações pausadas' : 'Apta para ação'}</span><span className="status-tag neutral">{selected.journey}</span></div></div><button className="icon-button" onClick={() => window.alert('Use Registrar resposta ou Registrar oposição para alterar o estado auditado da conta.')}><MoreHorizontal size={19}/></button></div><div className="score-explainer"><div className={`score-disc ${scoreTone(selected.score)}`}><strong>{selected.score}</strong><span>score</span></div><div><span className="eyebrow">SCORE EXPLICADO</span><strong>{selected.scoreReason}</strong><p>O score não autoriza contato: evidência, revisão, permissão e aprovação continuam obrigatórias.</p></div></div><div className="detail-grid"><div><SectionLabel icon={UsersRound} label="Contatos"/><div className="contact-stack">{selected.contacts.length === 0 ? <div className="empty-state">Nenhum contato cadastrado. Importe uma lista ou adicione o contato após validar a conta.</div> : selected.contacts.map((contact) => <div className="contact-card" key={contact.id}><div className="avatar small">{contact.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</div><div className="contact-details"><strong>{contact.name}</strong><span>{contact.role}</span><small>{contact.status} · {contact.reviewedAt || 'ainda não revisado'}</small><div className="contact-public-links">{contact.phone && <a href={`tel:${contact.phone.replace(/[^+\d]/g, '')}`}>Telefone: {contact.phone}</a>}{contact.linkedin && <a href={contact.linkedin} target="_blank" rel="noreferrer">Perfil LinkedIn ↗</a>}{contact.sourceUrl && <a href={contact.sourceUrl} target="_blank" rel="noreferrer">Fonte pública ↗</a>}{!contact.phone && !contact.linkedin && <small>Telefone e LinkedIn não encontrados nesta fonte.</small>}</div></div>{canReview && contact.status !== 'Revisado' && <button className="outline-button compact-action" onClick={() => onReviewContact(contact.id)}>Revisar</button>}{contact.email && <button className="icon-button compact" onClick={() => { void navigator.clipboard?.writeText(contact.email); }} title={`Copiar ${contact.email}`}><Mail size={15}/></button>}</div>)}</div></div><div><SectionLabel icon={Link2} label="Evidências"/>{selected.evidence.length === 0 ? <div className="empty-state">Nenhuma evidência ainda. Use Enriquecimento para criar uma sugestão rastreável.</div> : selected.evidence.map((evidence) => <a key={evidence.id} href={evidence.url} target="_blank" rel="noreferrer" className="evidence-card"><div className="evidence-icon"><BadgeCheck size={16}/></div><div><strong>{evidence.title}</strong><span>{evidence.excerpt}</span><small>{evidence.source} · {evidence.collectedAt} · {evidence.verified ? `Verificada por ${evidence.verifiedBy || 'revisor'}` : 'Não verificada'}</small></div><ExternalLink size={15}/></a>)}{canReview && selected.evidence.some((item) => !item.verified) && <div className="evidence-review-actions">{selected.evidence.filter((item) => !item.verified).map((item) => <button className="outline-button compact-action" key={item.id} onClick={() => onVerifyEvidence(item.id)}>Validar: {item.title}</button>)}</div>}</div></div><div className="timeline"><SectionLabel icon={Activity} label="Linha do tempo"/>{selected.activities.map((activity) => <div className="timeline-item" key={activity.id}><span className={`timeline-dot ${activity.kind.toLowerCase()}`}></span><div><strong>{activity.kind}</strong><p>{activity.text}</p><small>{activity.actor} · {activity.createdAt}</small></div></div>)}</div><div className="detail-actions"><button onClick={onReply} className="outline-button"><PauseCircle size={17}/> Registrar resposta</button><button onClick={onSuppress} className="danger-button"><ShieldCheck size={17}/> Registrar oposição</button></div></section></div></>;
}
function SectionLabel({ icon: Icon, label }: { icon: typeof UsersRound; label: string }) { return <div className="section-label"><Icon size={16}/><strong>{label}</strong></div>; }

function Campaigns({ campaign, accounts, onChange, onPauseAccount, onAssist, onQueue, onToast }: { campaign: Campaign; accounts: Account[]; onChange: (campaign: Campaign) => void; onPauseAccount: (accountId: string) => void; onAssist: (task: CampaignTask, action: 'profile' | 'copy' | 'complete') => Promise<void>; onQueue: (task: CampaignTask) => Promise<void>; onToast: (message: string) => void }) { const [draft, setDraft] = useState(campaign.copy.text); const [taskChannel, setTaskChannel] = useState<'LinkedIn' | 'WhatsApp'>('LinkedIn'); useEffect(() => setDraft(campaign.copy.text), [campaign.id, campaign.copy.text]); const hasChanged = draft !== campaign.copy.text; const saveCopy = () => onChange({ ...campaign, copy: { text: draft, revision: campaign.copy.revision + 1, state: 'Invalidado' } }); const approveCopy = () => { const eligible = campaign.accounts.some((id) => { const account = accounts.find((item) => item.id === id); return account && !account.paused && !account.suppressed && account.contacts.some((contact) => contact.status === 'Revisado') && account.evidence.some((evidence) => evidence.verified); }); if (!eligible) return onToast('A aprovação exige conta não pausada, contato revisado e evidência verificada.'); onChange({ ...campaign, copy: { ...campaign.copy, text: draft, state: 'Aprovado', approvedAt: nowLabel() } }); onToast('Copy aprovada com guarda de evidência.'); }; const createTask = () => { if (campaign.copy.state !== 'Aprovado') return onToast('Aprove a revisão atual da copy antes de criar uma tarefa.'); const account = accounts.find((item) => campaign.accounts.includes(item.id) && !item.paused && !item.suppressed && item.contacts.some((contact) => contact.status === 'Revisado' && (taskChannel === 'LinkedIn' ? Boolean(contact.linkedin) : Boolean(contact.phone))) && item.evidence.some((evidence) => evidence.verified)); const contact = account?.contacts.find((item) => item.status === 'Revisado' && (taskChannel === 'LinkedIn' ? Boolean(item.linkedin) : Boolean(item.phone))); const evidenceIds = account?.evidence.filter((item) => item.verified).map((item) => item.id) ?? []; if (!account || !contact || !evidenceIds.length) return onToast(taskChannel === 'WhatsApp' ? 'Para WhatsApp, a tarefa exige contato revisado com telefone e evidência verificada.' : 'A tarefa exige conta não pausada, contato revisado e evidência verificada.'); const channel: CampaignTask['channel'] = taskChannel; onChange({ ...campaign, tasks: [...campaign.tasks, { id: crypto.randomUUID(), accountId: account.id, contactId: contact.id, title: `Preparar abertura contextualizada para ${contact.name}`, channel, capability: channel === 'LinkedIn' ? 'Assistido' : 'API não oficial configurável', state: 'Aguardando revisão', due: 'Próximo dia útil', approval: { copyRevision: campaign.copy.revision, contactId: contact.id, channel, evidenceIds, approvedAt: campaign.copy.approvedAt ?? nowLabel() } }] }); onToast(`${channel} · tarefa criada e vinculada à revisão, destinatário e evidências.`); }; return <><div className="section-title"><div><p className="eyebrow">CAMPANHAS MULTICANAL</p><h1>{campaign.name}</h1><p>Cadência com contexto, revisão e guardas — nenhuma entrega externa é presumida.</p></div><span className="status-tag good">{campaign.status}</span></div><div className="campaign-stats"><div><span>ICP</span><strong>{campaign.icp}</strong></div><div><span>Contas</span><strong>{campaign.accounts.length} selecionadas</strong></div><div><span>Canais prioritários</span><strong><i className="linkedin-dot">in</i> LinkedIn assistido + <i className="whatsapp-dot">wa</i> WhatsApp configurável</strong></div></div><div className="campaign-grid"><section className="panel copy-editor"><div className="panel-head"><div><span className="eyebrow">COPY COM CONTEXTO</span><h2>Mensagem de abertura</h2></div><span className={`status-tag ${statusTone(hasChanged ? 'Invalidado' : campaign.copy.state)}`}>{hasChanged ? 'Alterada — aprovação inválida' : campaign.copy.state}</span></div><textarea value={draft} onChange={(event) => setDraft(event.target.value)}/><div className="copy-meta"><span>Revisão {campaign.copy.revision}{campaign.copy.approvedAt ? ` · aprovada em ${campaign.copy.approvedAt}` : ''}</span><div>{hasChanged && <button className="outline-button" onClick={saveCopy}>Salvar nova revisão</button>}<button className="new-button" onClick={approveCopy} disabled={hasChanged}><CopyCheck size={16}/> Aprovar texto</button></div></div><div className="copy-rule"><ShieldCheck size={17}/><p>A aprovação fica vinculada ao texto, destinatário, canal e evidências.</p></div></section><section className="panel sequence-panel"><div className="panel-head"><div><span className="eyebrow">JORNADA</span><h2>Cadência segura</h2></div></div><ol className="sequence"><li className="done"><span>1</span><div><strong>Contexto e evidência</strong><small>Fonte pública verificada</small></div><BadgeCheck size={17}/></li><li className="current"><span>2</span><div><strong>Revisão de copy</strong><small>Gestor aprova a revisão atual</small></div><CopyCheck size={17}/></li><li><span>3</span><div><strong>Tarefa assistida</strong><small>Operador executa na plataforma</small></div><UsersRound size={17}/></li><li><span>4</span><div><strong>Resposta ou pausa</strong><small>Inbox interrompe pendências</small></div><PauseCircle size={17}/></li></ol></section></div><section className="panel task-board"><div className="panel-head"><div><span className="eyebrow">FILA DE AÇÕES</span><h2>Próximas ações</h2></div><div className="task-create-controls"><select className="compact-select" value={taskChannel} onChange={(event) => setTaskChannel(event.target.value as 'LinkedIn' | 'WhatsApp')}><option value="LinkedIn">LinkedIn · Abridge</option><option value="WhatsApp">WhatsApp · Evolution</option></select><button className="new-button" onClick={createTask}><Plus size={16}/> Criar ação</button></div></div>{campaign.tasks.map((task) => { const account = accounts.find((item) => item.id === task.accountId); const contact = account?.contacts.find((item) => item.id === task.contactId); return <div className="task-row" key={task.id}><div className={`task-channel ${task.channel === 'WhatsApp' ? 'wa' : ''}`}>{task.channel === 'LinkedIn' ? 'in' : 'wa'}</div><div><strong>{task.title}</strong><span>{task.channel} · {account?.name} · {contact?.role} · {task.due}</span></div><span className="status-tag neutral">{task.capability}</span><span className={`status-tag ${statusTone(task.state)}`}>{task.state}</span><div className="task-actions">{task.channel === 'LinkedIn' && <button className="icon-button compact" onClick={() => void onAssist(task, 'profile')} title="Abrir perfil assistido"><ExternalLink size={14}/></button>}<button className="icon-button compact" onClick={() => void onAssist(task, 'copy')} title="Copiar copy aprovada"><Copy size={14}/></button>{task.state !== 'Concluído' && <><button className="outline-button compact-action" onClick={() => void onQueue(task)}>{task.channel === 'WhatsApp' ? 'Enviar pelo WhatsApp' : 'Enviar ao Abridge'}</button><button className="outline-button compact-action" onClick={() => void onAssist(task, 'complete')}>Registrar ação</button></>}<button className="icon-button compact" onClick={() => onPauseAccount(task.accountId)} title="Pausar ações da conta"><PauseCircle size={16}/></button></div></div>; })}</section></>; }

function Operations({ accounts, campaign, onComplete, onExport }: { accounts: Account[]; campaign: Campaign; onComplete: (task: CampaignTask) => void; onExport: () => void }) { const events = accounts.flatMap((account) => account.activities.map((activity) => ({ ...activity, account: account.name }))).slice(0, 15); return <><div className="section-title"><div><p className="eyebrow">OPERAÇÃO E AUDITORIA</p><h1>O que foi decidido, por quem e por quê.</h1><p>Registrar uma ação assistida não é afirmar entrega no provedor.</p></div><button className="outline-button" onClick={onExport}><Download size={17}/> Exportar auditoria</button></div><div className="operations-grid"><section className="panel"><div className="panel-head"><div><span className="eyebrow">FILA DE EXECUÇÃO</span><h2>Mensagens e handoffs</h2></div><span className="status-tag neutral">Ações humanas auditáveis</span></div>{campaign.tasks.map((task) => <div className="operation-task" key={task.id}><div className={`task-channel ${task.channel === 'WhatsApp' ? 'wa' : ''}`}>{task.channel === 'LinkedIn' ? 'in' : 'wa'}</div><div><strong>{task.title}</strong><span>{task.channel} · {task.capability} · execução humana requerida</span></div>{task.state === 'Concluído' ? <span className="status-tag good">Registrada</span> : <button className="new-button small" onClick={() => onComplete(task)}><ClipboardCheck size={15}/> Registrar ação assistida</button>}</div>)}</section><section className="panel capability-panel"><div className="panel-head"><div><span className="eyebrow">MATRIZ DE CAPACIDADE</span><h2>Canais e permissões</h2></div></div><Capability name="WhatsApp" detail="Health check via Evolution API quando configurada" state="Ver Configurações" good={false}/><Capability name="LinkedIn" detail="Perfil, copy e registro manual" state="Assistido" good={false}/><Capability name="ScrapeGraphAI" detail="Enriquecimento estruturado com chave e créditos verificados em Configurações" state="Verificar status" good={false}/></section></div><section className="panel audit-log"><div className="panel-head"><div><span className="eyebrow">TRILHA DE AUDITORIA</span><h2>Eventos recentes</h2></div><Zap size={18}/></div>{events.map((event) => <div className="audit-row" key={event.id}><span className="audit-symbol">{event.kind[0]}</span><div><strong>{event.kind} · {event.account}</strong><p>{event.text}</p></div><small>{event.actor}<br/>{event.createdAt}</small></div>)}</section></>; }
function Capability({ name, detail, state, good }: { name: string; detail: string; state: string; good: boolean }) { return <div className="capability"><div><strong>{name}</strong><span>{detail}</span></div><span className={`status-tag ${good ? 'good' : 'neutral'}`}>{state}</span></div>; }

function useChannelHealth() { const [health, setHealth] = useState<Record<string, ChannelHealth>>({}); const [loading, setLoading] = useState(false); const refresh = async () => { setLoading(true); try { const response = await fetch('/api/integrations/channels/health', { credentials: 'include' }); const payload = await response.json().catch(() => ({})); if (response.ok) setHealth(payload.channels ?? {}); } finally { setLoading(false); } }; useEffect(() => { void refresh(); }, []); return { health, loading, refresh }; }
function healthLabel(value?: ChannelHealth) { return value?.status === 'connected' ? 'Conectado' : value?.status === 'failed' ? 'Falhou' : 'Não configurado'; }
function Automation({ channels, agent, playbook, signals, accounts, onChange, onToast, onNavigate }: { channels: ChannelConnection[]; agent: AgentProfile; playbook: PlaybookStep[]; signals: Signal[]; accounts: Account[]; onChange: (next: Partial<ProspectraState>) => void; onToast: (message: string) => void; onNavigate: (view: View) => void }) { const [voice, setVoice] = useState(agent.voice); const [instruction, setInstruction] = useState(agent.instruction); const { health, loading, refresh } = useChannelHealth(); useEffect(() => { setVoice(agent.voice); setInstruction(agent.instruction); }, [agent.voice, agent.instruction]); const saveAgent = () => { onChange({ agent: { ...agent, voice, instruction, enabled: true, mode: 'Teste' } }); onToast('Agente salvo no workspace no modo Teste.'); }; const toggleStep = (id: string) => onChange({ playbook: playbook.map((step) => step.id === id ? { ...step, active: !step.active } : step) }); const simulate = () => onToast('Modo Teste: a próxima ação foi avaliada localmente; nenhuma mensagem externa foi enviada.'); return <><div className="section-title"><div><p className="eyebrow">AUTOMAÇÃO MULTICANAL</p><h1>Contexto antes do contato. <em>Conversa depois do sinal.</em></h1><p>O painel agora diferencia configuração, tarefa assistida e integração externa comprovada.</p></div><button className="new-button" onClick={simulate}><Bot size={17}/> Avaliar próxima ação</button></div><div className="automation-banner"><div className="automation-orb"><Bot size={19}/></div><div><strong>Modo seguro de operação</strong><span>O agente prepara contexto e tarefas. O envio só aparece como conectado quando o health check server-side comprova o provedor.</span></div><button className="outline-button" onClick={() => void refresh()}>{loading ? <LoaderCircle className="spin" size={15}/> : <Zap size={15}/>} Atualizar integrações</button></div><div className="channel-grid">{channels.map((channel) => { const current = health[channel.id]; return <section className="panel channel-card" key={channel.id}><div className="channel-head"><div className={`channel-logo ${channel.id}`}>{channel.id === 'whatsapp' ? 'wa' : 'in'}</div><div><span className="eyebrow">CANAL PRIORITÁRIO</span><h2>{channel.name}</h2></div><span className={`status-tag ${current?.status === 'connected' ? 'good' : current?.status === 'failed' ? 'danger' : 'neutral'}`}>{healthLabel(current)}</span></div><p>{current?.detail ?? channel.detail}</p><div className="provider-line"><span>Provedor</span><strong>{current?.provider ?? channel.provider}</strong></div><div className="provider-line"><span>Capacidade</span><strong>{current?.capability ?? (channel.id === 'linkedin' ? 'Assistido' : 'Não configurado')}</strong></div><div className="route-pills">{channel.routes.map((route) => <code key={route}>{route}</code>)}</div><button className="outline-button full-button" onClick={() => { onNavigate('settings'); onToast(`${channel.name}: veja o health check e os requisitos de configuração.`); }}><Link2 size={16}/> Ver configuração</button></section>; })}</div><div className="automation-grid"><section className="panel agent-studio"><div className="panel-head"><div><span className="eyebrow">AGENT STUDIO</span><h2>Prospectra Context Agent</h2></div><span className={`status-tag ${agent.enabled ? 'good' : 'neutral'}`}>{agent.enabled ? 'Ativo em Teste' : 'Rascunho'}</span></div><div className="agent-form"><label>Voz do agente<textarea value={voice} onChange={(event) => setVoice(event.target.value)}/></label><label>Regra de comportamento<textarea value={instruction} onChange={(event) => setInstruction(event.target.value)}/></label><label>Revisão<select value={agent.reviewMode} onChange={(event) => onChange({ agent: { ...agent, reviewMode: event.target.value as AgentProfile['reviewMode'] } })}><option>Toda mensagem</option><option>Somente respostas</option><option>Autonomia por playbook</option></select></label><div className="agent-actions"><button className="new-button" onClick={saveAgent}><BadgeCheck size={16}/> Salvar agente</button><span><ShieldCheck size={14}/> O modo Produção permanece bloqueado sem canal, limite e webhook comprovados.</span></div></div></section><section className="panel playbook-panel"><div className="panel-head"><div><span className="eyebrow">PLAYBOOK</span><h2>Outbound · Contexto → Conversa</h2></div><span className="status-tag good">{playbook.filter((step) => step.active).length} etapas ativas</span></div><div className="playbook-list">{playbook.map((step, index) => <div className={`playbook-step ${step.active ? 'active' : ''}`} key={step.id}><button className="step-number" onClick={() => toggleStep(step.id)}>{step.active ? '✓' : index + 1}</button><div><strong>{step.title}</strong><p>{step.detail}</p><small>{step.channel} · {step.wait}</small></div><ChevronRight size={16}/></div>)}</div></section></div><section className="panel signals-panel"><div className="panel-head"><div><span className="eyebrow">SIGNALS + HUMAN HANDOFF</span><h2>Conversas que merecem atenção</h2></div><button className="text-button" onClick={() => onNavigate('operations')}>Abrir fila de operação <ArrowUpRight size={15}/></button></div><div className="signals-list">{signals.map((signal) => { const account = accounts.find((item) => item.id === signal.accountId); return <div className="signal-row" key={signal.id}><div className={`channel-logo tiny ${signal.channel === 'WhatsApp' ? 'whatsapp' : 'linkedin'}`}>{signal.channel === 'WhatsApp' ? 'wa' : 'in'}</div><div className="signal-body"><strong>{signal.title}</strong><span>{account?.name} · {signal.detail}</span></div><span className={`priority ${signal.priority.toLowerCase()}`}>{signal.priority}</span><span className={`status-tag ${signal.state === 'Em handoff' ? 'danger' : signal.state === 'Resolvido' ? 'good' : 'neutral'}`}>{signal.state}</span><small>{signal.createdAt}</small></div>; })}</div></section></>; }

type ScrapeGraphHealth = { configured: boolean; status: string; remainingCredits?: number | null };
function useScrapeGraphHealth() { const [health, setHealth] = useState<ScrapeGraphHealth | null>(null); const [loading, setLoading] = useState(false); const refresh = async () => { setLoading(true); try { const response = await fetch('/api/integrations/scrapegraph/health', { credentials: 'include' }); const payload = await response.json().catch(() => ({})); if (response.ok) setHealth({ configured: Boolean(payload.configured), status: String(payload.status ?? 'unavailable'), remainingCredits: typeof payload.remainingCredits === 'number' ? payload.remainingCredits : null }); else setHealth({ configured: false, status: 'unavailable' }); } finally { setLoading(false); } }; useEffect(() => { void refresh(); }, []); return { health, loading, refresh }; }
function Settings({ onReset, onNavigate, onToast }: { onReset: () => void; onNavigate: (view: View) => void; onToast: (message: string) => void }) { const channels = useChannelHealth(); const scrape = useScrapeGraphHealth(); const refreshAll = () => { void channels.refresh(); void scrape.refresh(); }; const scrapeLabel = scrape.loading ? 'Verificando' : scrape.health?.status === 'connected' ? `Conectado · ${scrape.health.remainingCredits ?? '?'} créditos` : scrape.health?.status === 'insufficient_credits' ? 'Sem créditos' : scrape.health?.status === 'invalid_key' ? 'Chave inválida' : scrape.health?.status === 'awaiting_api_key' ? 'Chave pendente' : 'Provedor indisponível'; return <><div className="section-title"><div><p className="eyebrow">CONFIGURAÇÕES</p><h1>Integrações ligadas apenas quando comprovadas.</h1><p>Os estados abaixo vêm de health checks server-side; nenhum segredo é enviado ao navegador.</p></div><button className="outline-button" onClick={refreshAll}>{channels.loading || scrape.loading ? <LoaderCircle className="spin" size={15}/> : <Zap size={15}/>} Atualizar status</button></div><div className="settings-grid"><section className="panel settings-card"><div className="setting-icon purple"><Sparkles size={20}/></div><div><span className="eyebrow">ENRIQUECIMENTO</span><h2>ScrapeGraphAI v2</h2><p>Endpoint real server-side para extração individual e em lote. Uma chave configurada não substitui a revisão humana da evidência.</p><span className={`status-tag ${scrape.health?.status === 'connected' ? 'good' : 'neutral'}`}>{scrapeLabel}</span></div><button className="outline-button" onClick={() => onNavigate('enrichment')}>Abrir enriquecimento</button></section><section className="panel settings-card"><div className="setting-icon emerald"><MessageSquareText size={20}/></div><div><span className="eyebrow">CANAL PRIORITÁRIO</span><h2>WhatsApp · Evolution API</h2><p>{channels.health.whatsapp?.detail ?? 'Health check ainda não executado.'}</p><span className={`status-tag ${channels.health.whatsapp?.status === 'connected' ? 'good' : channels.health.whatsapp?.status === 'failed' ? 'danger' : 'neutral'}`}>{healthLabel(channels.health.whatsapp)}</span></div><button className="outline-button" onClick={() => onNavigate('automation')}>Abrir automação</button></section><section className="panel settings-card"><div className="setting-icon lilac"><UsersRound size={20}/></div><div><span className="eyebrow">CANAL PRIORITÁRIO</span><h2>LinkedIn</h2><p>{channels.health.linkedin?.detail ?? 'Health check ainda não executado.'} Ações assistidas continuam disponíveis.</p><span className={`status-tag ${channels.health.linkedin?.status === 'connected' ? 'good' : channels.health.linkedin?.status === 'failed' ? 'danger' : 'neutral'}`}>{channels.health.linkedin?.status === 'connected' ? 'Health técnico' : channels.health.linkedin?.status === 'failed' ? 'Falhou' : 'Assistido'}</span></div><button className="outline-button" onClick={() => onNavigate('campaigns')}>Abrir tarefas</button></section><section className="panel settings-card"><div className="setting-icon lilac"><BriefcaseBusiness size={20}/></div><div><span className="eyebrow">CRM</span><h2>Workspace autenticado</h2><p>Contas, campanhas, pausas e auditoria são sincronizados no Blob privado quando o Owner está autenticado.</p><span className="status-tag good">Persistência server-side</span></div><button className="outline-button" onClick={() => onNavigate('crm')}>Abrir CRM</button></section></div><EvolutionPanel onToast={onToast}/><ProspectingConnector/><AbridgePanel/><section className="panel data-controls"><div><span className="eyebrow">DADOS DEMONSTRATIVOS</span><h2>Restaurar base inicial</h2><p>Restaura o seed do workspace atual; use apenas para reiniciar a demonstração ou homologação.</p></div><button className="danger-button" onClick={onReset}>Restaurar base</button></section></>; }

type ProspectingConnection = { id: string; provider: 'unipile'; channel: 'linkedin' | 'whatsapp'; status: 'pending' | 'connected' | 'reconnect_required' | 'failed'; providerAccountId?: string; updatedAt: string; lastError?: string };
function ProspectingConnector() { const [connections, setConnections] = useState<ProspectingConnection[]>([]); const [loading, setLoading] = useState(true); const [connecting, setConnecting] = useState<'linkedin' | 'whatsapp' | null>(null); const [message, setMessage] = useState(''); const refresh = async () => { setLoading(true); try { const response = await fetch('/api/integrations/prospecting/accounts', { credentials: 'include' }); const payload = await response.json().catch(() => ({})); if (response.ok) setConnections(Array.isArray(payload.connections) ? payload.connections as ProspectingConnection[] : []); else setMessage('Não foi possível ler o estado das conexões de prospecção.'); } finally { setLoading(false); } }; useEffect(() => { void refresh(); }, []); const connect = async (channel: 'linkedin' | 'whatsapp') => { setConnecting(channel); setMessage(''); try { const response = await fetch('/api/integrations/prospecting/hosted-auth', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ channel }) }); const payload = await response.json().catch(() => ({})); if (!response.ok || typeof payload.url !== 'string') { setMessage(payload.error === 'unipile_not_configured' ? 'A conexão Hosted Auth exige UNIPILE_DSN, UNIPILE_API_KEY e UNIPILE_WEBHOOK_SECRET no Vercel.' : 'Não foi possível gerar um link de conexão agora.'); return; } window.location.assign(payload.url); } finally { setConnecting(null); } }; return <section className="panel data-controls prospecting-connector"><div><span className="eyebrow">MOTOR DE PROSPECÇÃO · CONEXÃO DE CONTAS</span><h2>Conectar conta com Hosted Auth</h2><p>Modelo inspirado no fluxo de provedor: o Prospectra pede um link temporário, o titular autentica a própria conta fora do app e o callback registra apenas o identificador da conta. O Prospectra nunca solicita senha, cookie ou perfil de navegador.</p>{message && <div className="owner-feedback error"><CircleAlert size={15}/><span>{message}</span></div>}<div className="connection-list">{loading ? <span>Consultando conexões…</span> : connections.length ? connections.map((connection) => <span className={`status-tag ${connection.status === 'connected' ? 'good' : connection.status === 'failed' ? 'danger' : 'neutral'}`} key={connection.id}>{connection.channel === 'linkedin' ? 'LinkedIn' : 'WhatsApp'} · {connection.status === 'connected' ? 'Conectada' : connection.status === 'pending' ? 'Aguardando autenticação' : connection.status === 'reconnect_required' ? 'Reconexão necessária' : 'Falhou'}</span>) : <span>Nenhuma conta conectada neste usuário.</span>}</div></div><div className="connector-actions"><button className="new-button" disabled={connecting !== null} onClick={() => void connect('linkedin')}>{connecting === 'linkedin' ? <LoaderCircle className="spin" size={16}/> : <Link2 size={16}/>} Conectar LinkedIn</button><button className="outline-button" disabled={connecting !== null} onClick={() => void connect('whatsapp')}>{connecting === 'whatsapp' ? <LoaderCircle className="spin" size={16}/> : <Link2 size={16}/>} Conectar WhatsApp</button><button className="text-button" onClick={() => void refresh()}><Zap size={15}/> Atualizar</button><small><strong>Desktop Bridge:</strong> alternativa sem assinatura de provedor, mas requer aplicativo assinado para Windows/macOS/Linux, máquina ligada, atualização automática e suporte operacional. Não está ativada no Vercel porque não é um app desktop.</small></div></section>;
}

type AbridgeDevice = { id: string; name: string; createdAt: string; updatedAt: string; lastSeenAt?: string; lastStatus?: string; lastPlatform?: string; active: boolean };
function AbridgePanel() { const [devices, setDevices] = useState<AbridgeDevice[]>([]); const [name, setName] = useState(''); const [token, setToken] = useState(''); const [loading, setLoading] = useState(false); const [message, setMessage] = useState(''); const refresh = async () => { try { const response = await fetch('/api/integrations/prospecting/bridge/devices', { credentials: 'include' }); const payload = await response.json().catch(() => ({})); if (response.ok) setDevices(Array.isArray(payload.devices) ? payload.devices as AbridgeDevice[] : []); } catch { setMessage('Não foi possível consultar os dispositivos Abridge.'); } }; useEffect(() => { void refresh(); }, []); const create = async () => { setLoading(true); setMessage(''); setToken(''); try { const response = await fetch('/api/integrations/prospecting/bridge/devices', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.error ?? 'bridge_pairing_failed'); setToken(String(payload.token ?? '')); setName(''); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Falha ao criar dispositivo.'); } finally { setLoading(false); } }; const revoke = async (id: string) => { await fetch(`/api/integrations/prospecting/bridge/devices?deviceId=${encodeURIComponent(id)}`, { method: 'DELETE', credentials: 'include' }); await refresh(); }; return <section className="panel data-controls prospecting-connector abridge-panel"><div><span className="eyebrow">DESKTOP BRIDGE · TODOS OS USUÁRIOS ATIVOS</span><h2>Prospectra Abridge</h2><p>Qualquer usuário ativo cadastrado pode criar seu próprio dispositivo. O Abridge mantém o Chrome e a sessão do LinkedIn no computador do operador; cada usuário vê e revoga somente os próprios dispositivos.</p>{message && <div className="owner-feedback error"><CircleAlert size={15}/><span>{message}</span></div>}{token && <div className="abridge-token-box"><strong>Token exibido uma única vez</strong><code>{token}</code><button className="text-button" onClick={() => { void navigator.clipboard?.writeText(token); setMessage('Token copiado. Cole-o no Abridge e não o compartilhe.'); }}><Copy size={14}/> Copiar token</button></div>}<div className="connection-list">{devices.length ? devices.map((device) => <span className={`status-tag ${device.lastStatus === 'online' ? 'good' : 'neutral'}`} key={device.id}>{device.name} · {device.lastStatus === 'online' ? `Online${device.lastPlatform ? ` · ${device.lastPlatform}` : ''}` : 'Pareado'}</span>) : <span>Nenhum desktop pareado.</span>}</div></div><div className="connector-actions"><label>Nome do computador<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Mac do André ou Windows do sócio" /></label><button className="new-button" disabled={loading} onClick={() => void create()}>{loading ? <LoaderCircle className="spin" size={16}/> : <Link2 size={16}/>} Criar pareamento</button>{devices.map((device) => <button className="danger-button" key={device.id} onClick={() => void revoke(device.id)}>Revogar {device.name}</button>)}<a className="outline-button" href="https://files.manuscdn.com/user_upload_by_module/session_file/310419663029693892/msyBOtxEqaDZfSiL.zip" target="_blank" rel="noreferrer"><Download size={15}/> Baixar Abridge para Windows</a><a className="outline-button" href="https://files.manuscdn.com/user_upload_by_module/session_file/310419663029693892/nNEUkFKReysCTznz.zip" target="_blank" rel="noreferrer"><Download size={15}/> Baixar para Mac M1/M2/M3/M4</a><a className="outline-button" href="https://files.manuscdn.com/user_upload_by_module/session_file/310419663029693892/aVqmYcllxhRrhNnP.zip" target="_blank" rel="noreferrer"><Download size={15}/> Baixar para Mac Intel</a><small><strong>Fluxo:</strong> qualquer usuário ativo cria seu token → instala o Abridge → cola o token → abre o Chrome local → faz login manual no LinkedIn. <strong>macOS:</strong> use o pacote Apple Silicon nativo em M1/M2/M3/M4; em Mac Intel, use o pacote Intel. Na primeira abertura, use clique secundário → Abrir.</small></div></section>; }

function AccountComposer({ owner, onClose, onCreate }: { owner: string; onClose: () => void; onCreate: (draft: { name: string; domain: string; sector: string; employees: string; journey: Account['journey']; owner: string }) => void }) { const [draft, setDraft] = useState({ name: '', domain: '', sector: '', employees: '', journey: 'Aquisição' as Account['journey'] }); return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal-card" onMouseDown={(event) => event.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">CRM · NOVA CONTA</span><h2>Cadastrar empresa</h2></div><button className="icon-button" onClick={onClose}><X size={17}/></button></div><p>Crie a conta agora; contatos e evidências entram depois de importação ou pesquisa rastreável.</p><div className="modal-form"><label>Nome da empresa<input autoFocus value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} required /></label><label>Domínio ou site<input value={draft.domain} onChange={(event) => setDraft({ ...draft, domain: event.target.value })} placeholder="empresa.com.br" required /></label><label>Setor<input value={draft.sector} onChange={(event) => setDraft({ ...draft, sector: event.target.value })} required /></label><label>Porte<input value={draft.employees} onChange={(event) => setDraft({ ...draft, employees: event.target.value })} placeholder="100–300" /></label><label>Jornada<select value={draft.journey} onChange={(event) => setDraft({ ...draft, journey: event.target.value as Account['journey'] })}><option>Aquisição</option><option>Expansão / ABM</option><option>Reativação</option></select></label></div><div className="modal-actions"><button className="outline-button" onClick={onClose}>Cancelar</button><button className="new-button" disabled={!draft.name.trim() || !draft.domain.trim() || !draft.sector.trim()} onClick={() => onCreate({ ...draft, owner })}><Plus size={16}/> Criar conta</button></div></div></div>; }
function LimitsDialog({ onClose }: { onClose: () => void }) { return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal-card limits-card" onMouseDown={(event) => event.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">CAPACIDADES E LIMITES</span><h2>O que é real hoje</h2></div><button className="icon-button" onClick={onClose}><X size={17}/></button></div><div className="limits-list"><div><BadgeCheck size={17}/><span><strong>Servidor pronto</strong> autenticação, Owner e Blob privado; ScrapeGraphAI e Office 365 exibem estado próprio e só operam após health/configuração.</span></div><div><ShieldCheck size={17}/><span><strong>Assistido</strong> LinkedIn: abrir perfil, copiar copy aprovada e registrar a ação humana.</span></div><div><CircleAlert size={17}/><span><strong>Configuração externa</strong> WhatsApp/Evolution e uma futura API autorizada do LinkedIn exigem credenciais, escopos, health check e webhook.</span></div><div><Database size={17}/><span><strong>Regra de operação</strong> resposta pausa a conta; oposição permanece suprimida; tarefa concluída não é entrega confirmada.</span></div></div><button className="new-button full" onClick={onClose}>Entendi</button></div></div>; }
